/* SPDX-License-Identifier: GPL-3.0-or-later - the firmware version: start-up screen, the menu's
 * About page, SysEx IDENTIFY, the USB device release number, and a tag the web installer
 * finds in the image ("TBOSS 0.3.0"). */
#ifndef TB_VERSION_H
#define TB_VERSION_H
#define TB_VERSION_MAJOR 2
#define TB_VERSION_MINOR 8
#define TB_VERSION_PATCH 0 /* 2.8.0 (2026-11-17): release 2.8 republished (a shadow update, still 2.8.0, its screens saying 2.8) with the fixes of the alphas 2.8.1 and 2.8.2 below (board-tested). 2.8.2 (alpha): from 2.8.1's bench (J5.5): a computer woken from sleep with no program reading the board's port left the board silent on both outputs, the given-up reply's last packet waiting in the endpoint; a TRS-only session now plays then too (TBR-047, main.c usb_route). 2.8.1 (alpha): the 2.8 fix review's four findings (docs/review/FINDINGS.md): a pattern chosen while the lanes are stopped sends no stray controller message (TBR-043, engine_play.c tp_lanes); a TRS-only session starts while a given-up reply still waits for the endpoint, so the pads play on the jack while the computer sleeps (TBR-044, main.c); the melody note on the play screen is the note Mono brings back (TBR-045, engine_effects.c unhide); Half or Double speed held while a DAW's song position jumps back goes on from there (TBR-046, engine_play.c). 2.8.0: release 2.8 (2026-11-16), the alphas 2.7.1-2.7.3 below (board-tested), named 2.8 on its screens. 2.7.3 (alpha): the last melody note played, with its octave, at the play screen's top right (a user's request: the key at top left, the melody at top right; every layout shows the note its pad sent). 2.7.2 (alpha): the 2.7 delta review's last two findings: a SysEx reply still going out when the computer sleeps or resets the bus is given up (TBR-039, main.c sysex_output), and a settings record's Layout byte past Melody's refused with Pads on All Melody too (TBR-042). 2.7.1 (alpha): the 2.7 delta review's fixes (docs/review/FINDINGS.md TBR-033 to TBR-038, TBR-040; TBR-041 the editor's): a CC lane whose controller or channel changes sends nothing until its next step sounds; the pattern lengths and Random lanes' rounds no longer built inside the masked pass; Half or Double speed held across a pattern's end. 2.7.0: release 2.7 (2026-11-15), republished the same day with the step screen's CH fixed (a CC or Off lane on AUTO showed CH1; now the channel it sends on, as the lane's Channel item), the 2.6.6-2.6.8 alphas below (board-tested), named 2.7 on its screens (after 2.6.2, 2.6.4 and 2.6.5, released under their whole numbers). 2.6.8 (alpha): the Toraiz Squid's sequencer ideas (a user's request): a lane's running directions (lanes.h: six paths over its steps as 4 x 4 blocks, and Mirror, Reverse, Ping-pong), a step's Lasts (1..4 steps) and Skip (taken out of the lane: lanes.h ln_timeline), Stutter 1/32, Triplet and Dotted and a Stutter kept looping by a double tap, Half and Double speed while held (engine_play.c tp_speed); the web editor's Interpolate. 2.6.7 (alpha): the Play page redrawn as Find key's guesses change (bench F3: LISTENING until a button). 2.6.6 (alpha): the progression library (Settings > Progressions > Library) and Find key (Settings > Play: the keys the notes from MIDI in fit best); the web editor's MIDI files, starter patterns and undo. 2.6.5: released as 2.6.5 (2026-11-14; board-tested as the 2.6.5 alpha), its screens saying 2.6.5. 2.6.5 (alpha): web editor edits no longer lost: main.c's midi_read stops reading while a complete SysEx message waits to be handled, so the next one (the Sequencer tab's quiet records, sent back to back with no reply) stays in the USB buffer instead of being dropped (since 1.9.3). 2.6.4: released as 2.6.4 (2026-11-14; board-tested as the 2.6.3 and 2.6.4 alphas), its screens saying 2.6.4. 2.6.4 (alpha): from 2.6.3's bench: a lane's first closing bend waits until the lane has sounded on its channel (a lane whose first step was off sent it on channel 1; since 2.6.2), and the CC lanes' per-pass cost back out of the idle loop (lane modes worked out only when the lanes change; let_go inline). 2.6.3 (alpha, toward 2.7; the Logic user's requests): a step's bend in tenths of a semitone (controls_steps.c tc_bend_tenths; eighths before), and CC lanes (lanes.h LN_CC): a lane kind whose steps send a controller value 0..127 on the lane's channel as the lane's controller (ln_lane.cc, set in the web editor; 1 the mod wheel), no notes, kept over rests and stops, slewed by Bend glide (engine_play.c lane_mode, engine.c lane_bend_candidate). 2.6.2: released as 2.6.2 (2026-11-14; board-tested as the 2.6.1 and 2.6.2 alphas), its screens saying 2.6.2. 2.6.2 (alpha): a step's bend in a recording, again (the user's Logic still drew ramps): a few ms (TP_LANE_LEAD_MS, 8) before a step whose bend differs, the lane's bend moves 1 toward it (1 of 16,384, not heard), so the old step ends with a point of its own at its own time (2.6.0 sent the old value again in the same transfer as the new one, and Logic kept one of the two); the repeat that remains (a chance step, a mute, a glide) is 1 toward the new value too (engine_play.c lane_closing, engine.c lane_bend_candidate). 2.6.1 (alpha, the first test build toward 2.7): pads from MIDI in (a user's request: another controller's pads, an Akai Force's, play the board's chords). Settings > MIDI > Pad ch (Off, 1..16) and Pad note (the first note, C2 unless set; shown while the channel is on): the channel's 48 notes from the first press the left half's pads, an octave a row from the bottom row up, C to B the twelve columns (midi_in.c tm_pad_of), with the note's velocity and its aftertouch (poly, or the channel's pressure) as the pad's pressure, entering where a touch is sensed (engine_pads.c tp_remote), so the chord, strum, arpeggiator, hold, note repeat, capture, recording and the pad's light follow as for a finger; on the step screen a note plays and edits nothing; the settings record's word 38 bytes 2-3. 2.6.0: release 2.6, the 2.5.x alphas below (2.5.1-2.5.5, board-tested), named 2.6 on its screens, with the step bend in a recording (a user's request): a lane's bend that changes 20 ms or more after its last message sends the old value once more first, so a DAW that draws a line between bends draws the step flat and then a jump (engine.c lane_bend_candidate), and Bend glide, a lane setting (ln_lane.glide, the pattern record's word 10, set in the web editor): a step's bend reached smoothly from the last step's over a quarter, half, three quarters or the whole of the step (engine_play.c tp_lanes). 2.5.5 (alpha): from the 2.5.2-2.5.4 bench round: a hard strike read early no longer plays near-silent (review TBR-032: a first reading in the lowest quarter of the velocity span waits one more reading and plays the higher of the two; engine_pads.c velocity_waits), and a note the MIDI map takes is a control, not a note playing (midi_in.c: it no longer lights the pads or joins a captured chord). 2.5.4 (alpha): named functions for the MIDI map (roadmap 2.6; controls.h TC_NAMED_, a sixth slot kind TC_CC_FUNCTION): 76 functions that do the same thing from every screen (a lane muted or soloed, every lane playing, a pattern by number, next or previous, the step option, the key, a mode button's scale, a preset loaded, a progression played, the step screen), set up in the web editor; the board's root and mode buttons and the functions share one piece of code each (tc_key, tc_scale_button, tc_load_preset, tc_lane_toggle, tc_lanes_on, tc_pattern_step, tc_step_option, tc_open_steps). 2.5.3 (alpha): the step screen's loop rate with a pattern playing (roadmap 2.6): a pass walks only the pads read and the pads whose touch changed (tp_frame, tc_frame: e->turned), and skips MPE's and poly aftertouch's walks when no half uses them; nothing plays or shows differently. 2.5.2 (alpha): the pattern's groove (Settings > Patterns: Swing, Swing grid, Density, Humanize; the pattern record's word 9). 2.5.1 (alpha): swing 25..75 with 50 straight (lanes, the arpeggiator; negative swing), slide (a tie into a step that plays overlaps it), Shift + left/right coarse on the step screen, the extras record (kind 21). 2.5.0: release 2.5, the 2.4.x alphas below (2.4.1-2.4.13, board-tested), named 2.5 on its screens. 2.4.13 (alpha): the MIDI map grows (roadmap D and A/B stage 1): 32 slots, each a CC, note or pitch bend on its own channel, a board button or a step option on the held steps (editor-only setup). 2.4.12 (alpha): pitch bend per step (roadmap C: BEND, Shift + M7, Settings > Steps > Bend range, only a lane with a channel to itself); the step screen's line 4 no longer repeats PLAY / STOP. 2.4.11 (alpha): the step screen's U1..U3 held set the lane's length, direction, swing; Shift + U1 swing, Shift + U2 rate (roadmap A). 2.4.10 (alpha): the lights take a melody pad's note directly (All Melody's loop rate). 2.4.9 (alpha): All Melody (docs/all-melody.md): Layout > Pads All Melody, every pad a melody note, the halves joined Stacked, Wide rows or Kalimba, the right half's octave, Split. 2.4.8 (alpha): the review's Stage 4, nothing the player notices: the DMA sources kept out of the core-coupled RAM (TBR-021), the stack's high-water mark for SWD (TBR-010), two bounds fixes (TBR-029); new native checks (TBR-022, TBR-023). 2.4.7 (alpha): storage, the review's step 3.5: a start that tidies the settings log shows SAVING SETTINGS at once but erases only 1.5 s after start-up, so a plug still being seated cannot cut power in the middle of it (TBR-008). 2.4.6 (alpha): storage, the review's steps 3.2-3.4: every flash write read back, a failed one says NOT SAVED, and compaction retries a failed record once and says NOT SAVED: RESTART if one is lost or the erase fails (TBR-018); compaction's copies in a static table, 12.9 KB off the stack, and a frame over 6,000 bytes fails the build (TBR-009); one CRC-32 a nibble at a time for the settings and the editor's protocol, each record's computed once at start (TBR-027). 2.4.5 (alpha): storage, the review's steps 3.1 and 3.6: a save writes one record a pass, so a pattern copied while another plays no longer holds playing up by tens of ms (TBR-007); the flash accelerator set by the firmware itself (wait states, prefetch, both caches, as measured), and the data cache flushed after each flash write (TBR-003). The velocity fix planned as 2.4.5 is skipped (decided 2026-11-11). 2.4.4 (alpha): the first test build of 2.5: the step screen's step number right-aligned (TBR-031); a trace of the velocity readings of the last 4 touches and of the last 4 at velocity 10 or less, for SWD (TBR-032, playing unchanged); the review's steps 1.5 to 1.9: the touch-button sampler's counters wrap (TBR-004), fail() spins instead of sleeping (TBR-005), an unfinished SysEx message expires after 1 s (TBR-006), MIDI-in transport and held notes cleared on a USB mount or suspend (TBR-026), a paste stores the lane's loop window and follow and keeps the lane's own solo (TBR-016), up to four loads and saves waiting at once (TBR-028). 2.4.3 (alpha): the review's steps 2.2 to 2.4: text drawn a glyph column at a time, so a screen redraw stalls the loop far less (TBR-014); a session restart outside the masked pass (TBR-015); the pad lights worked out 16 pads a pass, not all 96 in one (TBR-013 step 2). 2.4.2 (alpha): the review's steps 1.4 and 2.1: a latched I2C fault recovered after 30 ms, inside the held buttons' 200 ms grace (TBR-012); the pad lights worked out at most every 16 ms, not every pass, so the loop runs about three times as often and each pad is read sooner (TBR-013 step 1). 2.4.1 (alpha): the review's Stage 1 timing fixes: the pads' resting level found without a full sort (TBR-002), SysTick counts elapsed cycles so a long masked pass loses no time (TBR-001), Note Offs looked for only on channels that can owe one (TBR-011). 2.4.0 (released as 2.4, 2026-11-09; board-tested over five alpha builds): Settings > Lights > Out of scale and Dim (a user's request); the sequencer grows up: 8 lanes, 8 patterns and songs, mute and solo on the step screen's root buttons, M1..M7 choose the step option, live transpose from the chord pads, each lane's loop window, Fill on root button 9. 2.3: Modes (modal interchange: each chord row its own mode on the key's root, Row 2..4, Mel follows) with 2.2.1 and 2.1 in it; 2.3.1: the screen's changes in one DMA transfer (no top-down drawing); 2.3.2: a knob just learned stays quiet while its item is open (CCnn = shows); 2.3.3: the microtonal tunings dropped (2.2.0's; out of scope), a full 64-byte USB transfer no longer ends the session; 2.3.4: Modes' chord line names the mode in three letters (Edim MIX, D# AEO), the line under the key fits (MODE M1 P2 MODES); 2.3.5: Harm minor and Mel minor rows as HMIN, MMIN (G HMIN); 2.3.6: the pads' defaults +1000/+600/+3200 (were +700/+300/+2500). 2.2.1: notes due together in one USB transfer, MIDI in read before the engine, Step grid (4x4 blocks). 2.1: external MIDI control (the MIDI map, Settings > Control), Layout's first item named Melody. 2.0: the Turing pattern, chained progressions with each chord's chance, presets' own chord sets, U3 as Shift, Sleep and Shut down, the menu rebalanced and reordered, Spread of Bass, Fill, nudge and swing, Mutate, Stutter, lane transpose (1.9: the editor's tabs); every build to test has its own number (2.1.0, 2.1.1 ...) */
#define TB_STR2(x) #x
#define TB_STR(x) TB_STR2(x)
#define TB_VERSION TB_STR(TB_VERSION_MAJOR) "." TB_STR(TB_VERSION_MINOR) "." TB_STR(TB_VERSION_PATCH)
#define TB_VERSION_TAG "TBOSS " TB_VERSION
/* What the screens show. A public release (TB_RELEASE 1) is named by its major and minor version only:
 * "1.7" (released 2026-10-26: build 1.7.10, the step sequencer's second round, the 2020 promises, the
 * pads from each one's rest, tested on a board). A build being tested shows its whole number and
 * ALPHA ("1.7.11 ALPHA"). The tag, IDENTIFY and USB always carry the whole number (the installer
 * checks it). Before 1.7 releases were "x.y.0 BETA". 2.5 (2026-11): build 2.5.0, after the alphas 2.4.1-2.4.13.
 * 2.6 (2026-11): build 2.6.0, after the alphas 2.5.1-2.5.5. 2.6.2 (2026-11-14): build 2.6.2, after the alphas 2.6.1 and
 * 2.6.2, released under its whole number, so its screens say 2.6.2. 2.6.4 (2026-11-14): build 2.6.4, after the alphas
 * 2.6.3 and 2.6.4, the same; 2.6.5 (2026-11-14) after its alpha. 2.7 (2026-11-15): build 2.7.0, after the alphas
 * 2.6.6-2.6.8. 2.8 (2026-11-16): build 2.8.0, after the alphas 2.7.1-2.7.3. */
#define TB_RELEASE 1 /* release 2.8: build 2.8.0, its file replaced 2026-11-17 with the 2.8.1-2.8.2 fixes */
#if TB_RELEASE && TB_VERSION_PATCH
#define TB_VERSION_LABEL TB_VERSION /* 2.6.2: since 2.5 a release is x.y.0; one between them is named by its whole number */
#elif TB_RELEASE
#define TB_VERSION_LABEL TB_STR(TB_VERSION_MAJOR) "." TB_STR(TB_VERSION_MINOR)
#else
#define TB_VERSION_LABEL TB_VERSION " ALPHA"
#endif
/* The USB device release number is BCD, one digit for the patch: 9 stands for 9 and up there. */
#define TB_USB_BCD (TB_VERSION_MAJOR << 8 | TB_VERSION_MINOR << 4 | (TB_VERSION_PATCH > 9 ? 9 : TB_VERSION_PATCH))
#endif
